import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Group, 
  Vector3, 
  Color 
} from 'three/webgpu';
import { 
  uv, 
  texture, 
  vec3, 
  positionLocal, 
  normalLocal, 
  mix, 
  uniform 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const mainGroup = new Group();

  // 1. Stage Backdrop (ensuring we design-to-stage)
  const bgGeom = new PlaneGeometry(8, 6);
  // Vertical micro-gradient from surface to ink
  const bgMat = new MeshBasicNodeMaterial();
  const topColor = new Color(colors.surface);
  const bottomColor = new Color(colors.ink);
  const uBv = uv();
  bgMat.colorNode = mix(
    vec3(bottomColor.r, bottomColor.g, bottomColor.b),
    vec3(topColor.r, topColor.g, topColor.b),
    uBv.y
  );
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2);
  mainGroup.add(bgMesh);

  // 2. Interactive Feature Hero Plane with Displacement
  const geom = new PlaneGeometry(2.5, 1.8, 128, 128); // 1.8 Height, 2.5 Width
  const mat = new MeshBasicNodeMaterial();

  const uDispScale = uniform(0.12);
  const displacementMap = uniform(null);
  const mainMap = uniform(null);

  // Apply displacement & texture via WebGPU TSL nodes
  const uvCoord = uv();
  const dispValue = texture(displacementMap, uvCoord).r;

  // Warp local vertices based on depthMap
  mat.positionNode = positionLocal.add(normalLocal.mul(dispValue.mul(uDispScale)));
  mat.colorNode = texture(mainMap, uvCoord);

  const cardMesh = new THREE.Mesh(geom, mat);
  cardMesh.castShadow = true;
  cardMesh.receiveShadow = true;
  mainGroup.add(cardMesh);

  // Load textures securely
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      mainMap.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      displacementMap.value = tex;
    });
  }

  // Accent Edge Indicator (Focus Frame)
  const borderGeom = new PlaneGeometry(2.56, 1.86);
  const borderMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.15
  });
  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.set(0, 0, -0.02);
  mainGroup.add(borderMesh);

  // 3. Typographic Overlay (Value + Label on the core surface)
  // Clean readable ASCII metric
  const metricText = ctx.fontAtlas.createText('0.01s', {
    fontSize: 72,
    color: colors.paper,
    align: 'center'
  });
  metricText.position.set(0, 0.1, 0.15); // Layered outward
  mainGroup.add(metricText);

  const labelText = ctx.fontAtlas.createText('ACCURACY STABILIZED', {
    fontSize: 20,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  labelText.position.set(0, -0.35, 0.15);
  mainGroup.add(labelText);

  // 4. Motion / Settle Rig & Hover Triggers
  let isHovered = false;
  const hoverTargetZ = 0.15;
  const hoverTargetScale = 1.05;

  const currentScale = { val: 1 };
  const currentZ = { val: 0 };

  const updateTransform = () => {
    cardMesh.position.z = currentZ.val;
    cardMesh.scale.setScalar(currentScale.val);
    borderMesh.position.z = currentZ.val - 0.02;
    borderMesh.scale.setScalar(currentScale.val);
  };

  const enterTimeline = gsap.timeline({ paused: true });
  enterTimeline.to(currentZ, { val: hoverTargetZ, duration: 0.4, ease: 'power2.out', onUpdate: updateTransform })
               .to(currentScale, { val: hoverTargetScale, duration: 0.4, ease: 'power3.out', onUpdate: updateTransform }, 0)
               .to(borderMat, { opacity: 0.75, duration: 0.35 }, 0);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(currentScale, { val: 0.96, duration: 0.12, ease: 'back.out(2)', onUpdate: updateTransform });

  // Event handlers exposed via userData.handlers
  const handlers = {
    pointerover: (e) => {
      isHovered = true;
      enterTimeline.play();
    },
    pointerout: (e) => {
      isHovered = false;
      enterTimeline.reverse();
    },
    pointerdown: (e) => {
      pressTimeline.play();
    },
    pointerup: (e) => {
      pressTimeline.reverse();
      ctx.emit('hub-features.select', { id: config.id || 'features-stat' });
    }
  };

  mainGroup.userData.handlers = handlers;

  // 5. Cinematic Primitives Binding
  const primitivesInstances = [];
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](mainGroup, prim.params);
        if (inst) primitivesInstances.push(inst);
      }
    });
  }

  // Cleanup block
  mainGroup.userData.cleanup = () => {
    enterTimeline.kill();
    pressTimeline.kill();
    primitivesInstances.forEach((inst) => {
      if (typeof inst.cleanup === 'function') inst.cleanup();
    });
    geom.dispose();
    mat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    borderGeom.dispose();
    borderMat.dispose();
  };

  return mainGroup;
}
